 const complete='{"active":true,"evidenceRefs":["EVIDENCE-1"],"fields":{"CREATED_AT":"device-a","OBLIGATION":"must hold","REQ_ID":"REQ-1","STATUS":"CURRENT","UPDATED_AT":"device-b","VERSION":"V1"},"relationships":{"SOURCE_ID":"SOURCE-1"},"scope":{"inputVersion":"INPUT-v001"}}';
