  assert.deepEqual(observationsFromReports('verify-hash.mjs',[report]).map(row=>[row.checkId,row.passed]),[['canonical.content-complete-record-distinction',true]],'RECORD_DISTINCTION_CATALOG_SELECTOR_ORACLE');cases.push('selector-valid');
