 for(let index=0;index<faultPairs.length;index++)for(const [label,change]of [['missing',r=>r.faults.splice(index,1)],['duplicate',r=>r.faults.push(structuredClone(r.faults[index]))],['wrong-oracle',r=>r.faults[index].oracle='OTHER'],['generic-crash',r=>r.faults[index].stderr='UNRELATED_ERROR'],['exit-zero',r=>r.faults[index].exitCode=0],['coerced-exit',r=>r.faults[index].exitCode='1'],['not-detected',r=>r.faults[index].result='FAIL']])changes.push([`fault-${index}:${label}`,change]);
